const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const GRAPH_ROWS=[
{key:'org',question:'Wer entscheidet gemeinsam?',options:[['autonomous','Autonome Bandredaktionen'],['federated','Föderierte Arbeitsgruppen'],['central','Zentrale Redaktion']]},
{key:'host',question:'Wer trägt den Betrieb?',options:[['uni','Federführende Universität'],['academy','Gemeinsamer Akademieträger'],['external','Externer Dienst']]},
{key:'repos',question:'Wie werden Arbeitsrepos zugeschnitten?',options:[['mono','Ein Gesamtrepo'],['hybrid','Bereiche + Standards'],['volumes','Band-/Paketrepos']]},
{key:'data',question:'Wo liegt die maßgebliche Datenpflege?',options:[['git','Git-zentriert'],['hybrid','Hybrid: Zuständigkeit je Datenart'],['db','Datenbank-zentriert']]}
];
export function graphSVG(state=null,interactive=false){const w=1100,h=1480;let out=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="${interactive?'group':'img'}" aria-labelledby="dg-title dg-desc"><title id="dg-title">Entscheidungswege der Akademieedition</title><desc id="dg-desc">Organisation, Betrieb, Repository-Zuschnitt und Datenpflege verzweigen und führen zur gemeinsamen Integration zusammen. Nach Begutachtung und Freigaben werden Verlag, öffentliche Daten und Archiv bedient. Modell- und Hostwechsel benötigen erneute Prüfung.</desc><defs><marker id="dg-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#7e8c87"/></marker></defs><style>.dg-box{fill:#f1f4ed;stroke:#a6b6ae;stroke-width:1.5}.dg-choice{cursor:pointer}.dg-choice:focus rect{stroke:#a54b35;stroke-width:4}.dg-selected{fill:#233b42;stroke:#233b42}.dg-t{font:17px 'Segoe UI',Arial,sans-serif;fill:#233b42;text-anchor:middle}.dg-selected-text{fill:white}.dg-label{font:16px 'Segoe UI',Arial,sans-serif;fill:#a54b35;text-anchor:middle}.dg-line{fill:none;stroke:#a6b6ae;stroke-width:1.6;marker-end:url(#dg-arrow)}.dg-note{font:15px 'Segoe UI',Arial,sans-serif;fill:#516169;text-anchor:middle}</style><rect width="1100" height="1480" fill="#fffdf8"/><text x="550" y="40" class="dg-t" style="font-size:26px;font-weight:bold">Akademieedition: Entscheidungen verbinden</text><text x="550" y="72" class="dg-note">${state?'Aktuelle Auswahl dunkel markiert':'Neutrale Übersicht · mehrere Wege können tragfähig sein'}</text>`;
function line(x1,y1,x2,y2){out+=`<path class="dg-line" d="M${x1} ${y1}L${x2} ${y2}"/>`;}
function box(x,y,width,height,text,selected=false,attrs=''){out+=`<g ${attrs}><rect x="${x}" y="${y}" width="${width}" height="${height}" rx="12" class="dg-box${selected?' dg-selected':''}"/><text x="${x+width/2}" y="${y+height/2+6}" class="dg-t${selected?' dg-selected-text':''}">${esc(text)}</text></g>`;}
let previous=94;
GRAPH_ROWS.forEach((row,i)=>{const y=130+i*205;for(let j=0;j<3;j++){const x=35+j*355,cx=x+160;if(j===1){out+=`<path d="M550 ${previous}L550 ${y-28}" fill="none" stroke="#a6b6ae" stroke-width="1.6"/>`;line(550,y+14,cx,y+28);}else line(550,previous,cx,y+28);const [v,t]=row.options[j];box(x,y+28,320,64,t,state?.[row.key]===v,interactive?`class="dg-choice" role="button" tabindex="0" data-graph-key="${row.key}" data-graph-value="${v}" aria-label="${esc(row.question+' '+t)}" aria-pressed="${state?.[row.key]===v}"`:'');line(cx,y+92,550,y+147);}out+=`<text x="550" y="${y}" class="dg-label">${row.question}</text>`;out+=`<circle cx="550" cy="${y+150}" r="4" fill="#a6b6ae"/>`;previous=y+154;});
line(550,previous,550,970);box(260,970,580,64,'Geprüfte Datenpakete → gemeinsame Integration');line(550,1034,550,1080);box(260,1080,580,64,'Fixierter Prüfstand, Gutachten, Nachbearbeitung');line(550,1144,550,1190);box(260,1190,580,64,'Wissenschaftliche und passende rechtliche Freigaben');
for(const [x,t] of [[35,'Verlagspaket → Buch'],[390,'Öffentliche Daten → Web'],[745,'Ergebnisse + geschützter Prozess']]){line(550,1254,x+160,1300);box(x,1300,320,64,t);}
out+='<text x="550" y="1405" class="dg-note">Rückwege: Gutachten und Satzkorrekturen zurück in die maßgeblichen Daten.</text><text x="550" y="1432" class="dg-note">Host-/Modellwechsel: Export, Zuständigkeiten und Wiederaufbau erneut prüfen.</text><text x="550" y="1459" class="dg-note">Gemeinsam: Handbuch, wissenschaftliche Mandate und geregelte Zugänge.</text></svg>';return out;}
